"""Models of settlement-event.v1.schema.json (generated by A2C from the contract; edit the schema,
not this file)."""
from datetime import date, datetime  # noqa: F401
from decimal import Decimal  # noqa: F401
from typing import Literal, Optional

from pydantic import BaseModel, ConfigDict, Field, model_validator  # noqa: F401


class Adjustment(BaseModel):
    """Only on ledger.adjusted (added in v1, additive): a write-off or refund of the completed settlement."""
    model_config = ConfigDict(extra="forbid")
    adjustment_id: str = Field(pattern='^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$')
    type: Literal['WRITE_OFF', 'REFUND']
    amount: Decimal
    debit_account: str = Field(min_length=1)
    credit_account: str = Field(min_length=1)
    reason: str = Field(min_length=1)
    reference: str = Field(min_length=1)


class Settlement(BaseModel):
    """Settlement (generated)."""
    model_config = ConfigDict(extra="forbid")
    settlement_id: str = Field(pattern='^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$')
    payer_account: str = Field(min_length=1)
    payee_account: str = Field(min_length=1)
    amount: Decimal = Field(description='Decimal as a string, two fraction digits: no floating-point rounding.')
    currency: str = Field(pattern='^[A-Z]{3}$')
    status: Literal['RECEIVED', 'LEDGER_POSTED', 'COMPLETED', 'COMPENSATING', 'COMPENSATED', 'REJECTED']
    reason: Optional[str]


class SettlementEvent(BaseModel):
    """Published by settlement-service through its transactional outbox; consumed by audit-ai-service and (later) the reconciliation engine. Additive changes keep version 1; anything else is a new schema version."""
    model_config = ConfigDict(extra="forbid")
    event_id: str = Field(pattern='^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$', description='Unique per event; consumers de-duplicate on it.')
    event_type: Literal['ledger.posted', 'settlement.completed', 'settlement.compensated', 'settlement.rejected', 'ledger.adjusted']
    schema_version: Literal['1']
    occurred_at: datetime
    tenant_id: str = Field(min_length=1)
    correlation_id: str = Field(min_length=1)
    settlement: Settlement
    adjustment: Optional[Adjustment] = Field(default=None, description='Only on ledger.adjusted (added in v1, additive): a write-off or refund of the completed settlement.')

    @model_validator(mode="after")
    def _present_when(self):
        if (self.event_type == 'ledger.adjusted') != (self.adjustment is not None):
            raise ValueError("adjustment is present exactly when event_type is ledger.adjusted")
        return self
